/**
 * Extracts the `parent_tool_use_id` linking a subagent back to the Agent/Task
 * tool_use block that spawned it. Scans all assistant messages and returns the
 * first `parent_tool_use_id` field whose value is a string. Non-string values
 * (e.g. `null`) are ignored; returns undefined when no string value is found.
 */
function extractParentToolUseId(messages: readonly SessionMessage[]): string | undefined {
	for (const msg of messages) {
		if (msg.type !== 'assistant') {
			continue;
		}
		// The field may live on the SessionMessage envelope or on the inner message content.
		const envelope = (msg as { parent_tool_use_id?: unknown }).parent_tool_use_id;
		if (typeof envelope === 'string') {
			return envelope;
		}
		const inner = (msg.message as { parent_tool_use_id?: unknown } | null | undefined)?.parent_tool_use_id;
		if (typeof inner === 'string') {
			return inner;
		}
	}
	return undefined;
}

